    12	public class Database {
    13	    private static final Logger logger = LoggerFactory.getLogger(Database.class);
    14	    private final HikariDataSource dataSource;
    15	
    16	    public Database(String url, String user, String password) {
    17	        HikariConfig config = new HikariConfig();
