    29	        try (Connection conn = dataSource.getConnection()) {
    30	            Statement stmt = conn.createStatement();
    31	
    32	            stmt.execute("""
    33	                CREATE TABLE IF NOT EXISTS rooms (
    34	                    number INT PRIMARY KEY,
    35	                    type VARCHAR(20) NOT NULL,
    36	                    capacity INT NOT NULL,
    37	                    nightly_rate NUMERIC(10, 2) NOT NULL
    38	                )
    39	                """);
    40	
