    58	                    refund NUMERIC(10, 2),
    59	                    FOREIGN KEY (room_number) REFERENCES rooms(number)
    60	                )
    61	                """);
    62	
    63	            stmt.execute("""
    64	                CREATE TABLE IF NOT EXISTS messages (
    65	                    id SERIAL PRIMARY KEY,
    66	                    channel VARCHAR(20) NOT NULL,
    67	                    "to" VARCHAR(255) NOT NULL,
    68	                    subject VARCHAR(255) NOT NULL,
    69	                    body TEXT NOT NULL,
    70	                    status VARCHAR(20) NOT NULL
    71	                )
    72	                """);
    73	
    74	            stmt.execute("""
