    12	public class MessageService {
    13	    private final Database database;
    14	    private final boolean testMode;
    15	    private int messageId = 0;
    16	
    17	    public MessageService(Database database) {
    18	        this.database = database;
    19	        this.testMode = "true".equalsIgnoreCase(System.getenv("HOTEL_TEST_MODE"));
    20	        initializeMessageId();
    21	    }
    22	
    23	    private void initializeMessageId() {
    24	        try (Connection conn = database.getConnection()) {
    25	            String sql = "SELECT COALESCE(MAX(id), 0) FROM messages";
    26	            try (Statement stmt = conn.createStatement()) {
    27	                ResultSet rs = stmt.executeQuery(sql);
    28	                if (rs.next()) {
    29	                    messageId = rs.getInt(1);
    30	                }
    31	            }
    32	        } catch (SQLException e) {
    33	            throw new RuntimeException(e);
    34	        }
    35	    }
    36	
    37	    public void sendConfirmationEmail(String guestName, String guestEmail, String receipt) {
    38	        String subject = "Reserva confirmada - Pousada Maré Alta";
    39	        String body = "Olá, " + guestName + "!\n\n" +
    40	                "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
    41	                receipt + "\n\n" +
    42	                "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
    43	                "Até breve!";
    44	
    45	        sendMessage("EMAIL", guestEmail, subject, body);
    46	    }
    47	
    48	    public void sendMessage(String channel, String to, String subject, String body) {
    49	        String effectiveTo = to;
    50	        String effectiveSubject = subject;
    51	        String effectiveBody = body;
    52	        MessageStatus status = MessageStatus.SENT;
    53	
    54	        if (!EmailValidator.isValid(to)) {
    55	            effectiveSubject = subject;
    56	            effectiveBody = body;
    57	            status = MessageStatus.BLOCKED;
    58	            saveMessage("EMAIL", to, effectiveSubject, effectiveBody, status);
    59	            return;
    60	        }
    61	
    62	        if (testMode) {
    63	            effectiveTo = "testes@pousadamarealta.com.br";
    64	            effectiveSubject = "[TESTE] " + subject;
    65	            effectiveBody = "Destinatário original: " + to + "\n" + body;
    66	        } else {
    67	            effectiveTo = to;
    68	        }
    69	
    70	        saveMessage("EMAIL", effectiveTo, effectiveSubject, effectiveBody, status);
    71	
    72	        if (!testMode && status == MessageStatus.SENT) {
    73	            String copyTo = "arquivo@pousadamarealta.com.br";
    74	            String copySubject = "[Cópia] " + subject;
    75	            saveMessage("EMAIL", copyTo, copySubject, body, MessageStatus.SENT);
    76	        }
    77	    }
    78	
    79	    private void saveMessage(String channel, String to, String subject, String body, MessageStatus status) {
    80	        try (Connection conn = database.getConnection()) {
    81	            String sql = "INSERT INTO messages (channel, \"to\", subject, body, status) VALUES (?, ?, ?, ?, ?)";
    82	            try (PreparedStatement stmt = conn.prepareStatement(sql)) {
    83	                stmt.setString(1, channel);
    84	                stmt.setString(2, to);
    85	                stmt.setString(3, subject);
    86	                stmt.setString(4, body);
    87	                stmt.setString(5, status.name());
    88	                stmt.executeUpdate();
    89	            }
    90	        } catch (SQLException e) {
    91	            throw new RuntimeException(e);
    92	        }
    93	    }
    94	
    95	    public List<Message> getAllMessages() {
    96	        List<Message> messages = new ArrayList<>();
    97	        try (Connection conn = database.getConnection()) {
    98	            String sql = "SELECT id, channel, \"to\", subject, body, status FROM messages ORDER BY id";
    99	            try (Statement stmt = conn.createStatement()) {
   100	                ResultSet rs = stmt.executeQuery(sql);
   101	                while (rs.next()) {
   102	                    Message msg = new Message(
   103	                            rs.getInt("id"),
   104	                            rs.getString("channel"),
   105	                            rs.getString("to"),
   106	                            rs.getString("subject"),
   107	                            rs.getString("body"),
   108	                            MessageStatus.valueOf(rs.getString("status"))
   109	                    );
   110	                    messages.add(msg);
   111	                }
   112	            }
   113	        } catch (SQLException e) {
   114	            throw new RuntimeException(e);
   115	        }
   116	        return messages;
   117	    }
   118	}
