     1	package com.pousadamarealta.util;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.time.LocalDate;
     6	
     7	public class Pricing {
     8	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = BigDecimal.valueOf(1.20);
     9	    private static final BigDecimal DISCOUNT_RATE = BigDecimal.valueOf(0.15);
    10	    private static final int SCALE = 2;
    11	
    12	    public static boolean isHighSeason(LocalDate date) {
    13	        int month = date.getMonthValue();
    14	        int day = date.getDayOfMonth();
    15	
    16	        if (month == 7) return true;
    17	        if (month == 12 && day >= 15) return true;
    18	        if (month >= 1 && month <= 2) return true;
    19	
    20	        return false;
    21	    }
    22	
    23	    public static BigDecimal calculateNightlyRate(BigDecimal baseRate, LocalDate date) {
    24	        if (isHighSeason(date)) {
    25	            return baseRate.multiply(HIGH_SEASON_MULTIPLIER)
    26	                    .setScale(SCALE, RoundingMode.HALF_EVEN);
    27	        }
    28	        return baseRate.setScale(SCALE, RoundingMode.HALF_EVEN);
    29	    }
    30	
    31	    public static BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
    32	        BigDecimal subtotal = BigDecimal.ZERO;
    33	        LocalDate current = checkIn;
    34	
    35	        while (current.isBefore(checkOut)) {
    36	            BigDecimal nightlyRate = calculateNightlyRate(baseRate, current);
    37	            subtotal = subtotal.add(nightlyRate);
    38	            current = current.plusDays(1);
    39	        }
    40	
    41	        return subtotal.setScale(SCALE, RoundingMode.HALF_EVEN);
    42	    }
    43	
    44	    public static BigDecimal calculateDiscount(BigDecimal subtotal, String ratePlan) {
    45	        if ("NON_REFUNDABLE".equals(ratePlan)) {
    46	            return subtotal.multiply(DISCOUNT_RATE)
    47	                    .setScale(SCALE, RoundingMode.HALF_EVEN);
    48	        }
    49	        return BigDecimal.ZERO;
    50	    }
    51	
    52	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
    53	        return subtotal.subtract(discount)
    54	                .setScale(SCALE, RoundingMode.HALF_EVEN);
    55	    }
    56	
    57	    public static int getNights(LocalDate checkIn, LocalDate checkOut) {
    58	        return (int) checkIn.until(checkOut).getDays();
    59	    }
    60	}

