     3	public class EmailValidator {
     4	    public static boolean isValid(String email) {
     5	        if (email == null || email.isEmpty()) {
     6	            return false;
     7	        }
     8	
     9	        int atCount = 0;
    10	        int atIndex = -1;
    11	
    12	        for (int i = 0; i < email.length(); i++) {
    13	            if (email.charAt(i) == '@') {
    14	                atCount++;
    15	                atIndex = i;
    16	            }
    17	        }
    18	
    19	        if (atCount != 1) {
    20	            return false;
    21	        }
    22	
    23	        if (atIndex == 0 || atIndex == email.length() - 1) {
    24	            return false;
    25	        }
    26	
    27	        String domain = email.substring(atIndex + 1);
    28	        int dotCount = 0;
    29	        for (char c : domain.toCharArray()) {
    30	            if (c == '.') {
    31	                dotCount++;
    32	            }
    33	        }
    34	
    35	        if (dotCount == 0 || domain.startsWith(".") || domain.endsWith(".")) {
    36	            return false;
    37	        }
    38	
    39	        return true;
    40	    }
    41	}
