 21	
 22	    public List<Room> getAllRooms() {
 23	        List<Room> rooms = new ArrayList<>();
 24	        try (Connection conn = database.getConnection()) {
 25	            String sql = "SELECT number, type, capacity, nightly_rate FROM rooms ORDER BY number";
 26	            try (Statement stmt = conn.createStatement()) {
 27	                ResultSet rs = stmt.executeQuery(sql);
 28	                while (rs.next()) {
 29	                    Room room = new Room(
 30	                            rs.getInt("number"),
 31	                            rs.getString("type"),
 32	                            rs.getInt("capacity"),
