 44	    public Room getRoomByNumber(int number) throws SQLException {
 45	        try (Connection conn = database.getConnection()) {
 46	            String sql = "SELECT number, type, capacity, nightly_rate FROM rooms WHERE number = ?";
 47	            try (PreparedStatement stmt = conn.prepareStatement(sql)) {
 48	                stmt.setInt(1, number);
 49	                ResultSet rs = stmt.executeQuery();
 50	                if (rs.next()) {
 51	                    return new Room(
 52	                            rs.getInt("number"),
 53	                            rs.getString("type"),
 54	                            rs.getInt("capacity"),
 55	                            rs.getBigDecimal("nightly_rate")
 56	                    );
 57	                }
 58	            }
 59	        }
 60	        return null;
 61	    }
 62	
 63	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
 64	                                        LocalDate checkIn, LocalDate checkOut, int guests, String ratePlan)
 65	            throws SQLException {
 66	        Room room = getRoomByNumber(roomNumber);
 67	        if (room == null) {
 68	            throw new RuntimeException("ROOM_NOT_FOUND");
 69	        }
 70	
 71	        if (guests < 1 || guests > room.capacity) {
 72	            throw new RuntimeException(guests > room.capacity ? "CAPACITY_EXCEEDED" : "INVALID_REQUEST");
 73	        }
 74	
 75	        if (checkOut.isBefore(checkIn) || checkOut.equals(checkIn)) {
 76	            throw new RuntimeException("INVALID_REQUEST");
 77	        }
 78	
 79	        if (isRoomUnavailable(roomNumber, checkIn, checkOut)) {
 80	            throw new RuntimeException("ROOM_UNAVAILABLE");
 81	        }
 82	
 83	        int nights = Pricing.getNights(checkIn, checkOut);
 84	        BigDecimal subtotal = Pricing.calculateSubtotal(room.nightlyRate, checkIn, checkOut);
 85	        BigDecimal discount = Pricing.calculateDiscount(subtotal, ratePlan);
 86	        BigDecimal total = Pricing.calculateTotal(subtotal, discount);
 87	
 88	        try (Connection conn = database.getConnection()) {
 89	            String sql = """
 90	                INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf,
 91	                                         check_in, check_out, guests, rate_plan, nights,
 92	                                         subtotal, discount, total, status, amount_paid)
 93	                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'PENDING', 0)
 94	                """;
 95	            try (PreparedStatement stmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
 96	                stmt.setInt(1, roomNumber);
 97	                stmt.setString(2, guestName);
 98	                stmt.setString(3, guestEmail);
 99	                stmt.setString(4, guestCpf);
100	                stmt.setDate(5, Date.valueOf(checkIn));
101	                stmt.setDate(6, Date.valueOf(checkOut));
102	                stmt.setInt(7, guests);
103	                stmt.setString(8, ratePlan);
104	                stmt.setInt(9, nights);
105	                stmt.setBigDecimal(10, subtotal);
106	                stmt.setBigDecimal(11, discount);
107	                stmt.setBigDecimal(12, total);
108	                stmt.executeUpdate();
109	
110	                ResultSet keys = stmt.getGeneratedKeys();
111	                int id = 0;
112	                if (keys.next()) {
113	                    id = keys.getInt(1);
114	                }
115	
116	                return getReservationById(id);
117	            }
118	        }
119	    }
120	
121	    public Reservation getReservationById(int id) throws SQLException {
122	        try (Connection conn = database.getConnection()) {
123	            String sql = """
124	                SELECT id, room_number, guest_name, guest_email, guest_cpf,
125	                       check_in, check_out, guests, rate_plan, nights,
126	                       subtotal, discount, total, status, amount_paid, refund
127	                FROM reservations WHERE id = ?
128	                """;
129	            try (PreparedStatement stmt = conn.prepareStatement(sql)) {
130	                stmt.setInt(1, id);
131	                ResultSet rs = stmt.executeQuery();
132	                if (rs.next()) {
133	                    return new Reservation(
134	                            rs.getInt("id"),
135	                            rs.getInt("room_number"),
136	                            rs.getString("guest_name"),
137	                            rs.getString("guest_email"),
138	                            rs.getString("guest_cpf"),
139	                            rs.getDate("check_in").toLocalDate(),
140	                            rs.getDate("check_out").toLocalDate(),
141	                            rs.getInt("guests"),
142	                            RatePlan.valueOf(rs.getString("rate_plan")),
143	                            rs.getInt("nights"),
144	                            rs.getBigDecimal("subtotal"),
145	                            rs.getBigDecimal("discount"),
146	                            rs.getBigDecimal("total"),
147	                            ReservationStatus.valueOf(rs.getString("status")),
148	                            rs.getBigDecimal("amount_paid"),
149	                            rs.getBigDecimal("refund")
150	                    );
151	                }
152	            }
153	        }
154	        return null;
155	    }
156	
157	    public Reservation confirmReservation(int reservationId) throws SQLException {
158	        Reservation reservation = getReservationById(reservationId);
159	        if (reservation == null) {
160	            throw new RuntimeException("RESERVATION_NOT_FOUND");
161	        }
162	
163	        if (!reservation.status.equals(ReservationStatus.PENDING)) {
164	            throw new RuntimeException("OPERATION_NOT_ALLOWED");
165	        }
166	
167	        try (Connection conn = database.getConnection()) {
168	            String sql = "UPDATE reservations SET status = 'CONFIRMED', amount_paid = ? WHERE id = ?";
169	            try (PreparedStatement stmt = conn.prepareStatement(sql)) {
170	                stmt.setBigDecimal(1, reservation.total);
171	                stmt.setInt(2, reservationId);
172	                stmt.executeUpdate();
173	            }
174	        }
175	
176	        Reservation updated = getReservationById(reservationId);
177	        String receipt = generateReceipt(updated);
178	        messageService.sendConfirmationEmail(reservation.guestName, reservation.guestEmail, receipt);
179	
180	        return updated;
181	    }
