183	    public Reservation checkIn(int reservationId) throws SQLException {
184	        Reservation reservation = getReservationById(reservationId);
185	        if (reservation == null) {
186	            throw new RuntimeException("RESERVATION_NOT_FOUND");
187	        }
188	
189	        if (!reservation.status.equals(ReservationStatus.CONFIRMED)) {
190	            throw new RuntimeException("OPERATION_NOT_ALLOWED");
191	        }
192	
193	        try (Connection conn = database.getConnection()) {
194	            String sql = "UPDATE reservations SET status = 'CHECKED_IN' WHERE id = ?";
195	            try (PreparedStatement stmt = conn.prepareStatement(sql)) {
196	                stmt.setInt(1, reservationId);
197	                stmt.executeUpdate();
198	            }
199	        }
200	
201	        return getReservationById(reservationId);
