203	
204	    public Reservation checkOut(int reservationId) throws SQLException {
205	        Reservation reservation = getReservationById(reservationId);
206	        if (reservation == null) {
207	            throw new RuntimeException("RESERVATION_NOT_FOUND");
208	        }
209	
210	        if (!reservation.status.equals(ReservationStatus.CHECKED_IN)) {
211	            throw new RuntimeException("OPERATION_NOT_ALLOWED");
212	        }
213	
214	        try (Connection conn = database.getConnection()) {
215	            String sql = "UPDATE reservations SET status = 'CHECKED_OUT' WHERE id = ?";
216	            try (PreparedStatement stmt = conn.prepareStatement(sql)) {
217	                stmt.setInt(1, reservationId);
218	                stmt.executeUpdate();
219	            }
220	        }
221	
222	        return getReservationById(reservationId);
223	    }
