225	    public Reservation cancelReservation(int reservationId) throws SQLException {
226	        Reservation reservation = getReservationById(reservationId);
227	        if (reservation == null) {
228	            throw new RuntimeException("RESERVATION_NOT_FOUND");
229	        }
230	
231	        if (!reservation.status.equals(ReservationStatus.PENDING) &&
232	            !reservation.status.equals(ReservationStatus.CONFIRMED)) {
233	            throw new RuntimeException("OPERATION_NOT_ALLOWED");
234	        }
235	
236	        BigDecimal refund = BigDecimal.ZERO;
237	        if (reservation.status.equals(ReservationStatus.CONFIRMED)) {
238	            if (reservation.ratePlan.equals(RatePlan.STANDARD)) {
239	                refund = reservation.amountPaid;
240	            }
241	        }
242	
243	        try (Connection conn = database.getConnection()) {
244	            String sql = "UPDATE reservations SET status = 'CANCELLED', refund = ? WHERE id = ?";
245	            try (PreparedStatement stmt = conn.prepareStatement(sql)) {
246	                stmt.setBigDecimal(1, refund);
247	                stmt.setInt(2, reservationId);
248	                stmt.executeUpdate();
249	            }
250	        }
251	
252	        return getReservationById(reservationId);
253	    }
