255	    public boolean isRoomUnavailable(int roomNumber, LocalDate checkIn, LocalDate checkOut) throws SQLException {
256	        try (Connection conn = database.getConnection()) {
257	            String sql = """
258	                SELECT COUNT(*) FROM reservations
259	                WHERE room_number = ?
260	                AND status != 'CANCELLED'
261	                AND check_in < ?
262	                AND check_out > ?
263	                """;
264	            try (PreparedStatement stmt = conn.prepareStatement(sql)) {
265	                stmt.setInt(1, roomNumber);
266	                stmt.setDate(2, Date.valueOf(checkOut));
267	                stmt.setDate(3, Date.valueOf(checkIn));
268	                ResultSet rs = stmt.executeQuery();
269	                if (rs.next()) {
270	                    return rs.getInt(1) > 0;
271	                }
272	            }
273	        }
274	        return false;
275	    }
