277	    private String generateReceipt(Reservation reservation) throws SQLException {
278	        Room room = getRoomByNumber(reservation.roomNumber);
279	        String nightsText = reservation.nights == 1 ? "1 diária" : reservation.nights + " diárias";
280	
281	        StringBuilder receipt = new StringBuilder();
282	        receipt.append("Comprovante de reserva nº ").append(reservation.id).append("\n");
283	        receipt.append("Hóspede: ").append(reservation.guestName)
284	               .append(" (CPF ").append(formatCpf(reservation.guestCpf)).append(")\n");
285	        receipt.append("Quarto: ").append(reservation.roomNumber).append(" (").append(room.type).append(")\n");
286	        receipt.append("Entrada: ").append(formatDate(reservation.checkIn))
287	               .append(" | Saída: ").append(formatDate(reservation.checkOut))
288	               .append(" | ").append(nightsText).append("\n");
289	        receipt.append("Diárias: ").append(formatMoney(reservation.subtotal)).append("\n");
290	
291	        if (reservation.discount.compareTo(BigDecimal.ZERO) > 0) {
292	            receipt.append("Desconto: ").append(formatMoney(reservation.discount)).append("\n");
293	        }
294	
295	        receipt.append("Total: ").append(formatMoney(reservation.total));
296	
297	        return receipt.toString();
298	    }
299	
300	    public String getReceipt(int reservationId) throws SQLException {
301	        Reservation reservation = getReservationById(reservationId);
302	        if (reservation == null) {
303	            throw new RuntimeException("RESERVATION_NOT_FOUND");
304	        }
305	
306	        if (!reservation.status.equals(ReservationStatus.CONFIRMED) &&
307	            !reservation.status.equals(ReservationStatus.CHECKED_IN) &&
308	            !reservation.status.equals(ReservationStatus.CHECKED_OUT)) {
309	            throw new RuntimeException("OPERATION_NOT_ALLOWED");
310	        }
311	
312	        return generateReceipt(reservation);
313	    }
314	
315	    private String formatCpf(String cpf) {
316	        if (cpf.length() == 11) {
317	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
318	                   cpf.substring(6, 9) + "-" + cpf.substring(9);
319	        }
320	        return cpf;
321	    }
322	
323	    private String formatDate(LocalDate date) {
324	        return String.format("%02d/%02d/%04d", date.getDayOfMonth(), date.getMonthValue(), date.getYear());
325	    }
326	
327	    private String formatMoney(BigDecimal amount) {
328	        return "R$ " + String.format("%.2f", amount).replace(".", ",");
329	    }
330	}
