101	public class ReservationHandler {
102	    private final ReservationService reservationService;
103	    private final ObjectMapper objectMapper = new ObjectMapper();
104	
105	    public ReservationHandler(ReservationService reservationService) {
106	        this.reservationService = reservationService;
107	    }
108	
109	    public void createReservation(Context ctx) {
110	        try {
111	            Map<String, Object> body = objectMapper.readValue(ctx.body(), Map.class);
112	
113	            Integer roomNumber = ((Number) body.get("roomNumber")).intValue();
114	            String guestName = (String) body.get("guestName");
115	            String guestEmail = (String) body.get("guestEmail");
116	            String guestCpf = (String) body.get("guestCpf");
117	            String checkInStr = (String) body.get("checkIn");
118	            String checkOutStr = (String) body.get("checkOut");
119	            Integer guests = ((Number) body.get("guests")).intValue();
120	            String ratePlan = (String) body.get("ratePlan");
121	
122	            if (roomNumber == null || guestName == null || guestEmail == null || guestCpf == null ||
123	                checkInStr == null || checkOutStr == null || guests == null || ratePlan == null) {
124	                ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "Missing required fields"));
125	                return;
126	            }
127	
128	            LocalDate checkIn = LocalDate.parse(checkInStr);
129	            LocalDate checkOut = LocalDate.parse(checkOutStr);
130	
131	            try {
132	                Reservation reservation = reservationService.createReservation(
133	                        roomNumber, guestName, guestEmail, guestCpf,
134	                        checkIn, checkOut, guests, ratePlan
135	                );
136	                ctx.status(201).json(reservationToJson(reservation));
137	            } catch (RuntimeException e) {
138	                handleError(ctx, e.getMessage());
139	            }
140	        } catch (DateTimeParseException e) {
141	            ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "Invalid date format"));
142	        } catch (Exception e) {
143	            ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", e.getMessage()));
144	        }
145	    }
146	
147	    public void getReservation(Context ctx) {
148	        try {
149	            int id = Integer.parseInt(ctx.pathParam("id"));
150	            Reservation reservation = reservationService.getReservationById(id);
151	
152	            if (reservation == null) {
153	                ctx.status(404).json(Map.of("error", "RESERVATION_NOT_FOUND", "message", "Reservation not found"));
154	            } else {
155	                ctx.json(reservationToJson(reservation));
156	            }
157	        } catch (SQLException e) {
158	            ctx.status(500).json(Map.of("error", "INTERNAL_ERROR", "message", e.getMessage()));
159	        }
160	    }
