193	        } catch (SQLException e) {
194	            ctx.status(500).json(Map.of("error", "INTERNAL_ERROR", "message", e.getMessage()));
195	        }
196	    }
197	
198	    public void checkOut(Context ctx) {
199	        try {
200	            int id = Integer.parseInt(ctx.pathParam("id"));
201	            Reservation reservation = reservationService.checkOut(id);
202	            String receipt = reservationService.getReceipt(id);
203	
204	            Map<String, Object> response = new HashMap<>(reservationToJson(reservation));
205	            response.put("document", receipt);
206	
207	            ctx.json(response);
208	        } catch (RuntimeException e) {
209	            handleError(ctx, e.getMessage());
210	        } catch (SQLException e) {
211	            ctx.status(500).json(Map.of("error", "INTERNAL_ERROR", "message", e.getMessage()));
212	        }
213	    }
214	
215	    public void getDocument(Context ctx) {
216	        try {
217	            int id = Integer.parseInt(ctx.pathParam("id"));
218	            Reservation reservation = reservationService.getReservationById(id);
219	            if (reservation == null) {
220	                ctx.status(404).json(Map.of("error", "RESERVATION_NOT_FOUND", "message", "Reservation not found"));
221	                return;
222	            }
223	
224	            String receipt = reservationService.getReceipt(id);
225	
226	            Map<String, Object> document = new HashMap<>();
227	            document.put("title", "Comprovante de reserva");
228	            document.put("reservationId", reservation.id);
229	            document.put("guestName", reservation.guestName);
230	            document.put("guestCpf", formatCpf(reservation.guestCpf));
231	            document.put("roomNumber", reservation.roomNumber);
232	            document.put("roomType", reservation.roomNumber == 101 || reservation.roomNumber == 102 ? "STANDARD" :
233	                                      reservation.roomNumber == 201 || reservation.roomNumber == 202 ? "DELUXE" : "SUITE");
234	            document.put("checkIn", formatDateForJson(reservation.checkIn));
235	            document.put("checkOut", formatDateForJson(reservation.checkOut));
236	            document.put("nights", reservation.nights);
237	            document.put("subtotal", formatMoney(reservation.subtotal));
238	            document.put("discount", formatMoney(reservation.discount));
239	            document.put("total", formatMoney(reservation.total));
240	
241	            ctx.json(document);
242	        } catch (RuntimeException e) {
243	            handleError(ctx, e.getMessage());
244	        } catch (SQLException e) {
245	            ctx.status(500).json(Map.of("error", "INTERNAL_ERROR", "message", e.getMessage()));
246	        }
247	    }
248	
249	    private Map<String, Object> reservationToJson(Reservation r) {
250	        Map<String, Object> map = new HashMap<>();
251	        map.put("id", r.id);
252	        map.put("roomNumber", r.roomNumber);
253	        map.put("guestName", r.guestName);
254	        map.put("guestEmail", r.guestEmail);
255	        map.put("guestCpf", r.guestCpf);
256	        map.put("checkIn", formatDateForJson(r.checkIn));
257	        map.put("checkOut", formatDateForJson(r.checkOut));
258	        map.put("guests", r.guests);
259	        map.put("ratePlan", r.ratePlan.name());
260	        map.put("nights", r.nights);
261	        map.put("subtotal", formatMoney(r.subtotal));
262	        map.put("discount", formatMoney(r.discount));
263	        map.put("total", formatMoney(r.total));
264	        map.put("status", r.status.name());
265	        map.put("amountPaid", formatMoney(r.amountPaid));
266	        if (r.refund != null) {
267	            map.put("refund", formatMoney(r.refund));
268	        } else {
269	            map.put("refund", null);
270	        }
271	        return map;
272	    }
273	
274	    private String formatMoney(java.math.BigDecimal amount) {
275	        return String.format("%.2f", amount);
276	    }
277	
278	    private String formatCpf(String cpf) {
279	        if (cpf.length() == 11) {
280	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
281	                   cpf.substring(6, 9) + "-" + cpf.substring(9);
282	        }
283	        return cpf;
284	    }
285	
286	    private String formatDateForJson(LocalDate date) {
287	        return String.format("%04d-%02d-%02d", date.getYear(), date.getMonthValue(), date.getDayOfMonth());
288	    }
289	
290	    private void handleError(Context ctx, String error) {
291	        switch (error) {
292	            case "ROOM_NOT_FOUND":
293	                ctx.status(404).json(Map.of("error", "ROOM_NOT_FOUND", "message", "Room not found"));
294	                break;
295	            case "RESERVATION_NOT_FOUND":
296	                ctx.status(404).json(Map.of("error", "RESERVATION_NOT_FOUND", "message", "Reservation not found"));
297	                break;
298	            case "ROOM_UNAVAILABLE":
299	                ctx.status(409).json(Map.of("error", "ROOM_UNAVAILABLE", "message", "Room is unavailable for these dates"));
300	                break;
301	            case "OPERATION_NOT_ALLOWED":
302	                ctx.status(409).json(Map.of("error", "OPERATION_NOT_ALLOWED", "message", "This operation is not allowed for this reservation"));
303	                break;
304	            case "CAPACITY_EXCEEDED":
305	                ctx.status(422).json(Map.of("error", "CAPACITY_EXCEEDED", "message", "Number of guests exceeds room capacity"));
306	                break;
307	            case "INVALID_REQUEST":
308	                ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "Invalid request"));
309	                break;
310	            default:
311	                ctx.status(500).json(Map.of("error", "INTERNAL_ERROR", "message", error));
312	        }
313	    }
314	}
