203	
204	            Map<String, Object> response = new HashMap<>(reservationToJson(reservation));
205	            response.put("document", receipt);
206	
207	            ctx.json(response);
208	        } catch (RuntimeException e) {
209	            handleError(ctx, e.getMessage());
